#include &lt;bits/stdc++.h&gt;using namespace std;vector&lt;int&gt; parent, sz;void init(int n)&#123;    parent.resize(n + 1);    sz.assign(n + 1, 1);    for (int i = 1; i &lt;= n; i++)&#123;        parent[i] = i;    &#125;&#125;int find(int x)&#123;    if (parent[x] == x) return x;    return parent[x] = find(parent[x]);&#125;void merge(int a, int b)&#123;    int ra = find(a);    int rb = find(b);    if (ra == rb) return;    if (sz[ra] &lt; sz[rb]) swap(ra, rb);    parent[rb] = ra;    sz[ra] += sz[rb];&#125;int main()&#123;    ios::sync_with_stdio(false);    cin.tie(nullptr);    int n, m, p;    cin &gt;&gt; n &gt;&gt; m &gt;&gt; p;    init(n);    for (int i = 0; i &lt; m; i++)&#123;        int a, b;        cin &gt;&gt; a &gt;&gt; b;        merge(a, b);    &#125;    for (int i = 0; i &lt; p; i++)&#123;        int u, v;        cin &gt;&gt; u &gt;&gt; v;        cout &lt;&lt; (find(u) == find(v) ? &quot;Yes&quot; : &quot;No&quot;) &lt;&lt; &#x27;\n&#x27;;    &#125;    return 0;&#125;

P16265 [蓝桥杯 2026 省 Python B 组] 蓝小圈这集是带权并查集，要多加三个数组来存一下活跃度。

own[x]：个人动态

lazyAdd[fa[x]]：圈层热议

d[x]：合并时的历史差额。两个圈子合并时，它们之前各自被“圈层热议”加过不同的值，合并后要保证每个人原来的值不乱


这个要注意一下，op &#x3D; 4的时候，不能写ll ans = own[x] + d[x] + lazyAdd[find(x)];，但具体为什么ai胡扯一堆我也没看懂。
#include &lt;bits/stdc++.h&gt;using namespace std;#define ll long longvector&lt;int&gt; fa, sz;vector&lt;ll&gt; d, own, lazyAdd;void init (int n)&#123;    fa.resize(n);    sz.assign(n, 1);    d.assign(n, 0);    own.assign(n, 0);    lazyAdd.assign(n, 0);    for (int i = 0; i &lt; n; i++)&#123;        fa[i] = i;    &#125;&#125;int find(int x)&#123;    if (fa[x] == x) return x;    int p = fa[x];    int root = find(p);    d[x] += d[p];    fa[x] = root;    return fa[x] = find(fa[x]);&#125;void merge(int a, int b)&#123;    int ra = find(a);    int rb = find(b);    if (ra == rb) return;    if (sz[ra] &lt; sz[rb]) swap(ra, rb);    fa[rb] = ra;    d[rb] = lazyAdd[rb] - lazyAdd[ra];    sz[ra] += sz[rb];&#125;int main()&#123;    ios::sync_with_stdio(false);    cin.tie(nullptr);        int n, q;    cin &gt;&gt; n &gt;&gt; q;        init(n + 1);    for (int i = 1; i &lt;= q; i++)&#123;        int op;        cin &gt;&gt; op;        if (op == 1)&#123;            int x, y;            cin &gt;&gt; x &gt;&gt; y;            merge(x, y);        &#125;        else if (op == 2)&#123;            int x;            ll a;            cin &gt;&gt; x &gt;&gt; a;            own[x] += a;        &#125;        else if (op == 3)&#123;            int x;            ll a;            cin &gt;&gt; x &gt;&gt; a;            lazyAdd[find(x)] += a;        &#125;        else&#123;            int x;            cin &gt;&gt; x;            int r = find(x);            ll ans = own[x] + d[x] + lazyAdd[r];            cout &lt;&lt; ans &lt;&lt; &quot;\n&quot;;        &#125;    &#125;    return 0;&#125;

P2097 资料分发 1有多少个连通块，就要往多少个电脑里输入数据，统计有多少连通块就可以了
#include &lt;bits/stdc++.h&gt;using namespace std;#define ll long longvector&lt;int&gt; parent, sz;void init(int n)&#123;    parent.resize(n);    sz.assign(n, 1);    for (int i = 0; i &lt; n; i++)&#123;        parent[i] = i;    &#125;&#125;int find(int x)&#123;    if (parent[x] == x) return x;    return parent[x] = find(parent[x]);&#125;void merge(int a, int b)&#123;    int ra = find(a);    int rb = find(b);    if (ra == rb) return;    if (sz[ra] &lt; sz[rb]) swap(ra, rb);    parent[rb] = ra;    sz[ra] += sz[rb];&#125;int main()&#123;    ios::sync_with_stdio(false);    cin.tie(nullptr);        int n, m;    cin &gt;&gt; n &gt;&gt; m;    if (n == 0)&#123;        cout &lt;&lt; 0;        return 0;    &#125;    init(n + 1);    for(int i = 1; i &lt;= m; i++)&#123;        int p, q;        cin &gt;&gt; p &gt;&gt; q;        merge(p, q);    &#125;    int ans = 0;    for (int i = 1; i &lt;= n; i++)&#123;        if (find(i) == i) ans++;    &#125;        cout &lt;&lt; ans;        return 0;&#125;

