#include &lt;bits/stdc++.h&gt;using namespace std;#define ll long longvector&lt;int&gt; fa, sz;void init(int n)&#123;    fa.resize(n);    sz.assign(n, 1);    for (int i = 0; i &lt; n; i++)&#123;        fa[i] = i;    &#125;&#125;int find(int x)&#123;    if (fa[x] == x) return x;    return fa[x] = find(fa[x]);&#125;void merge(int a, int b)&#123;    int ra = find(a);    int rb = find(b);    if (ra == rb) return;    if(sz[ra] &lt; sz[rb]) swap(ra, rb);    fa[rb] = ra;    sz[ra] += sz[rb];&#125;int main()&#123;    ios::sync_with_stdio(false);    cin.tie(nullptr);        int n, m;    cin &gt;&gt; n &gt;&gt; m;    init(n + 1);    for (int i = 1; i &lt;= m; i++)&#123;        int z, x, y;        cin &gt;&gt; z &gt;&gt; x &gt;&gt; y;        if (z == 1)&#123;            merge(x, y);        &#125;        if (z == 2)&#123;            if (find(x) == find(y))&#123;                cout &lt;&lt; &quot;Y\n&quot;;            &#125;            else cout &lt;&lt; &quot;N\n&quot;;        &#125;    &#125;        return 0;&#125;

